'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const {words:WORDS,forms:FORMS,rules:RULES,packs:PACKS}=LatinData;
let state=Workshop.readChapter('latin56-v1'),session=null,answered=false,helped=false,triedTypo=false,direction='de',selectedPair='56',area='vokabeln';
const p=()=>state.profiles.find(p=>p.id===state.active);
function save(){Workshop.saveChapter('latin56-v1',state);Workshop.updateName()}
function initProfile(){if(!p())return false;for(const x of ['stats','notes'])p()[x]||={};p().seen||=[];p().history||=[];if(!p().legacyImported){let old=Workshop.legacy();WORDS.filter(w=>w.chapter<=3).forEach(w=>{let v=old['w:'+w.latin];if(v!==undefined&&!p().stats[w.id])p().stats[w.id]={ok:Math.max(0,v-1),errors:v<0?1:0,last:0,due:0,imported:true}});p().legacyImported=true;save()}return true}
const stat=id=>p().stats[id]||{ok:0,errors:0,due:0,last:0};const stable=id=>(stat(id).ok||0)>=2;
function shuffle(items){let a=[...items];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
const pairWords=pair=>WORDS.filter(w=>w.pair===pair);
function adverbs(){return WORDS.filter(w=>w.small)}
function route(){if(!initProfile()){$('#app').innerHTML='<section class="card"><h1>Dein Lernplatz</h1><p>Wähle zuerst deinen Namen auf der gemeinsamen Startseite.</p><a href="../#profile">Profil wählen</a></section>';return}const hash=location.hash.slice(1);let m=hash.match(/^(vokabeln|grammatik|kurzproben)(?:-(12|34|56))?$/);if(hash==='adverbien'){area='adverbien';adverbHome()}else{area=m?.[1]||'vokabeln';if(m?.[2])selectedPair=m[2];if(area==='kurzproben')testsHome(m?.[2]);else if(m?.[2])packHome();else home()}$('.wl-nav').hidden=area==='kurzproben';for(const a of document.querySelectorAll('[data-tab]'))a.classList.toggle('active',a.dataset.tab===(area==='adverbien'?'vokabeln':area));Workshop.updateName()}
function home(){window.scrollTo({top:0,behavior:'auto'});session=null;let grammar=area==='grammatik';$('#app').innerHTML=`<div class="topic">Latein / ${grammar?'Formen und Satzbau':'Feste Wortschatz-Doppelpacks'}</div><h1>${grammar?'Grammatik':'Vokabeln'}</h1><p class="muted">${grammar?'Die Formen passend zum Lernstand, getrennt vom Wortschatz.':'Ein Doppelpack ist immer ein gemeinsamer Wortschatz. In einer vollständigen Runde werden alle seine Wörter abgefragt.'}</p><div class="cards">${Object.entries(PACKS).map(([pair,pack])=>`<section class="card pack ${grammar?'grammar':''}"><span class="badge">${grammar?'Grammatik':pairWords(pair).length+' Lernwörter und Formen'}</span><h2>${pack.title}</h2><p>${grammar?{12:'Nominativ Einzahl/Mehrzahl · Verben in der 3. Person',34:'Akkusativ Einzahl/Mehrzahl · alle Personen der Verben',56:'Dativ · Vokativ · Imperativ'}[pair]:'Der gesamte Wortschatz aus beiden Kapiteln – gemeinsam lernen und abfragen.'}</p><button data-open="${pair}">Doppelpack öffnen</button></section>`).join('')}</div>${!grammar?'<section class="card"><h2>Adverbien & kleine Wörter</h2><p>Bildszenen, Merksätze, Beispielsätze und gezielter Abruf. Die Wörter aus allen Doppelpacks werden hier zusätzlich gesammelt.</p><a href="#adverbien">Zum Spezialtrainer</a></section>':''}`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>location.hash=area+'-'+b.dataset.open)}
function packHome(){window.scrollTo({top:0,behavior:'auto'});session=null;let grammar=area==='grammatik',ws=pairWords(selectedPair),pack=PACKS[selectedPair];Workshop.visit(grammar?'latinGrammar':'latinVocab');$('#app').innerHTML=`<div class="topic">${grammar?'Grammatik':'Vokabeln'}</div><h1>${pack.title}</h1><div class="row"><a href="#${area}">Alle Doppelpacks</a><span class="badge">${grammar?'Formen getrennt üben':ws.length+' Einträge · ein fester Wortschatz'}</span></div>${grammar?`<section class="card"><h2>Verstehen und anwenden</h2><div class="row">${pack.groups.map(g=>`<button data-rule="${g}">${g==='verb'?'Verbformen':g[0].toUpperCase()+g.slice(1)}</button>`).join('')}</div><p>Erst die Regel, dann einzelne Formen bilden und bestimmen.</p><button class="secondary" id="grammarMix">Formen gemischt üben</button></section>`:`<section class="card"><h2>Den gesamten Doppelpack lernen</h2><p>Alle ${ws.length} Einträge kommen vor. Die Lernphase führt jeweils sechs Wörter mit Merkhilfe, Auswahl und eigenem Abruf durch – danach folgt die nächste Portion desselben Doppelpacks.</p><button id="learnPack">Doppelpack lernen</button><div class="row" style="margin-top:16px"><button class="secondary" id="mcPack">Alle Wörter · Multiple Choice</button><button class="secondary" id="writePack">Alle Wörter · selbst abrufen</button></div><p><label for="direction">Abfragerichtung beim freien Abruf</label><br><select id="direction" style="font:inherit;padding:10px;max-width:100%"><option value="de">Latein → Deutsch</option><option value="la">Deutsch → Latein</option></select></p><p class="small muted">${ws.filter(w=>stable(w.id)).length}/${ws.length} mehrfach ohne Hilfe abgerufen. Eine passende Bedeutung reicht; mehrere richtige Bedeutungen sind ebenfalls erlaubt.</p></section>`}<section class="card"><h2>Weiter festigen</h2><div class="row"><button id="repeat">${grammar?'Grammatikfehler':'Vokabelfehler'} wiederholen</button><a href="#kurzproben-${selectedPair}">Zur gemeinsamen Kurzprobe →</a></div><p class="small muted">Vokabeln und Grammatik werden im eigenen Bereich „Kurzproben“ gemeinsam geprüft.</p></section>${p().latinSession?'<p><button class="secondary" id="resumeSaved">Gespeicherte Runde fortsetzen</button></p>':''}${!grammar?`<details class="card"><summary>Alle Wörter dieses Doppelpacks</summary><table class="wordlist"><tbody>${ws.map(w=>`<tr><td>${esc(w.latin)}</td><td>${esc(w.answers.join('; '))}</td></tr>`).join('')}</tbody></table></details>`:''}`;if(grammar){document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>rule(b.dataset.rule));$('#grammarMix').onclick=()=>startForms()}else{$('#learnPack').onclick=()=>startLearn(ws);$('#mcPack').onclick=()=>begin('Alle Wörter · '+pack.title,shuffle(ws).map(w=>vq(w,'de','choice')));$('#writePack').onclick=()=>begin('Freier Abruf · '+pack.title,shuffle(ws).map(w=>vq(w,$('#direction').value)))}$('#repeat').onclick=()=>repeat(grammar);if($('#resumeSaved'))$('#resumeSaved').onclick=resume}
function mnemonic(w){let choice=p().mnemonicChoices?.[w.id];if(choice===0)return w.anchor;if(choice===1)return w.alternative||w.anchor;return p().notes[w.id]||w.anchor}
function switchMnemonic(w){p().mnemonicChoices||={};let current=p().mnemonicChoices[w.id]??(p().notes[w.id]?2:0);p().mnemonicChoices[w.id]=(current+1)%(p().notes[w.id]?3:2);save()}
function figure(w){if(w.panel!==undefined){let panel=w.panel,positions=[['0','0'],['-100%','0'],['0','-100%'],['-100%','-100%']],pos=positions[panel],src=w.atlas===6?'data:image/webp;base64,':w.atlas?`memory-${w.atlas}.webp`:'adverbien.png';return `<figure class="memory-figure"><div class="memory-scene"><img loading="lazy" src="${src}" alt="${esc(w.scene)}" style="left:${pos[0]};top:${pos[1]}"><span class="scene-word ${w.atlas?'':'scene-word-legacy'}">${esc(w.latin)}</span></div><figcaption>${esc(w.scene)}</figcaption></figure>`}return ''}
function adverbHome(){window.scrollTo({top:0,behavior:'auto'});session=null;Workshop.visit('latinAdverbs');let ws=adverbs().sort((a,b)=>a.chapter-b.chapter);$('#app').innerHTML=`<a href="#vokabeln">← Zu den Vokabel-Doppelpacks</a><div class="topic">Spezialtrainer / ${ws.length} kleine Wörter und Wendungen</div><h1>Adverbien & kleine Wörter</h1><p class="muted">31 kleine Wörter, 31 Merkszenen. Erst mit Bild lernen, dann mit Auswahl üben und schließlich ohne Bild selbst abrufen.</p><section class="card"><h2>Merken und abrufen</h2><div class="row"><button id="learnAdverbs">Alle kleinen Wörter lernen</button><button class="secondary" id="mcAdverbs">Mit Auswahl üben</button><button class="secondary" id="writeAdverbs">Ohne Auswahl abrufen</button><button class="secondary" id="repeatAdverbs">Fehlerstellen</button></div><p class="small muted">Eigene Merkhilfen kannst du auf jeder Lernkarte speichern. Die Auswahlhilfe zählt noch nicht als freier Abruf.</p></section><div class="grid">${ws.map(w=>`<section class="card"><span class="badge">${esc(w.category)}</span><h2>${esc(w.latin)}</h2><p><b>${esc(w.answers.join('; '))}</b></p>${figure(w)}<div class="anchor">${esc(mnemonic(w))}</div><p><i>${esc(w.sentence||'')}</i><br>${esc(w.translation||'')}</p><div class="row"><button class="secondary" data-adverb="${w.id}">Dieses Wort festigen</button><button class="secondary" data-alternative="${w.id}">Andere Merkhilfe</button></div></section>`).join('')}</div>`;$('#learnAdverbs').onclick=()=>startLearn(ws,true);$('#mcAdverbs').onclick=()=>begin('Kleine Wörter · Auswahl',shuffle(ws).map(w=>vq(w,'de','choice')));$('#writeAdverbs').onclick=()=>begin('Kleine Wörter · eigener Abruf',shuffle(ws).map(w=>vq(w)));$('#repeatAdverbs').onclick=()=>repeat(false,true);document.querySelectorAll('[data-alternative]').forEach(b=>b.onclick=()=>{let w=WORDS.find(w=>w.id===b.dataset.alternative);switchMnemonic(w);b.closest('section').querySelector('.anchor').textContent=mnemonic(w);b.textContent='Merkhilfe gewechselt'});document.querySelectorAll('[data-adverb]').forEach(b=>b.onclick=()=>startLearn([WORDS.find(w=>w.id===b.dataset.adverb)],true))}
function vq(w,dir='de',mode='write'){return {id:w.id,type:'vocab',word:w,dir,mode,prompt:dir==='de'?w.latin:w.answers.join('; '),answers:dir==='de'?w.answers:[w.latin.split(',')[0]],aliases:dir==='de'?(w.aliases||[]):[],why:w.anchor}}
function fq(f){return {...f,type:'form',mode:'write'}}
function formPool(){return FORMS.filter(f=>f.pair===selectedPair&&f.group!=='unterscheiden')}
function startForms(group){let qs=formPool().filter(f=>!group||f.group===group);begin('Grammatik · '+PACKS[selectedPair].title,shuffle(qs).slice(0,12).map(fq))}
function rule(group){window.scrollTo({top:0,behavior:'auto'});let rs=group==='verb'&&selectedPair==='12'?RULES.verb12:RULES[group];$('#app').innerHTML=`<button class="secondary" id="back">Zur Grammatikübersicht</button><section class="card"><div class="topic">${PACKS[selectedPair].title}</div><h1>${esc(rs[0])}</h1><div class="rule tags">${esc(rs[1])}</div><p>${esc(rs[2])}</p><button id="practice">Formen üben</button></section>`;$('#back').onclick=packHome;$('#practice').onclick=()=>startForms(group)}
function startLearn(ws,special=false){let queue=[];for(let offset=0;offset<ws.length;offset+=6){let portion=ws.slice(offset,offset+6);queue.push(...portion.map(w=>vq(w,'de','study')),...shuffle(portion).map(w=>vq(w,'de','choice')),...shuffle(portion).map(w=>vq(w)),...shuffle(portion).map(w=>vq(w)))}begin(special?'Kleine Wörter festigen':'Doppelpack lernen · '+PACKS[selectedPair].title,queue)}
function repeat(grammar,special=false){let qs=grammar?formPool().filter(f=>stat(f.id).errors&&!stable(f.id)).map(fq):(special?adverbs():pairWords(selectedPair)).filter(w=>stat(w.id).errors&&!stable(w.id)).map(w=>vq(w));if(!qs.length){$('#app').innerHTML='<section class="card"><h1>Keine offenen Fehlerstellen.</h1><p>Du kannst alle Wörter oder Formen weiter üben.</p><button id="back">Zurück</button></section>';$('#back').onclick=()=>overview();return}begin(grammar?'Grammatikfehler':'Vokabelfehler',shuffle(qs))}
function rotate(a,n){return a.slice(n).concat(a.slice(0,n))}
function grammarExam(pair,version){let groups=PACKS[pair].groups,pool=FORMS.filter(f=>f.pair===pair&&f.group!=='unterscheiden'&&!f.prompt.includes('Gaius')),out=[];for(const g of groups){let items=pool.filter(f=>f.group===g),count=12/groups.length;out.push(...items.slice(version*count,version*count+count).map(fq))}return out}
function combinedQuestions(pair,version){let words=pairWords(pair),vs=(version?[...words].reverse():words).map(w=>vq(w)),gs=grammarExam(pair,version),out=[];let used=0;vs.forEach((q,i)=>{out.push(q);let target=Math.floor((i+1)*gs.length/vs.length);while(used<target)out.push(gs[used++])});return out}
function testsHome(pair){$('.wl-nav').hidden=true;window.scrollTo({top:0,behavior:'auto'});session=null;Workshop.visit('latinTests');if(!pair){$('#app').innerHTML=`<div class="topic">Latein / Schulaufgaben-Vorbereitung</div><h1>Kurzproben</h1><p class="muted">Vokabeln und Grammatik gemeinsam. Zwei feste, vergleichbar schwere Varianten pro Doppelpack.</p><div class="cards">${Object.entries(PACKS).map(([id,pack])=>`<section class="card pack"><span class="badge">Kurzprobe A & B</span><h2>${pack.title}</h2><p>Alle ${pairWords(id).length} Vokabeleinträge und zwölf passende Grammatikaufgaben.</p><a class="button-link" href="#kurzproben-${id}">Kurzproben öffnen</a></section>`).join('')}</div>${p().latinSession?'<section class="card"><h2>Deine gespeicherte Runde</h2><button id="resumeSaved">Runde fortsetzen</button></section>':''}`;if($('#resumeSaved'))$('#resumeSaved').onclick=resume;return}selectedPair=pair;let ws=pairWords(pair);$('#app').innerHTML=`<a href="#kurzproben">← Alle Kurzproben</a><div class="topic">Vokabeln + Grammatik</div><h1>${PACKS[pair].title}</h1><section class="card"><h2>Was kommt dran?</h2><p>Der gesamte Wortschatz aus beiden Kapiteln: <b>${ws.length} Vokabeleinträge</b>. Dazu <b>zwölf Grammatikaufgaben</b> zu ${PACKS[pair].groups.map(g=>g==='verb'?'Verbformen':g[0].toUpperCase()+g.slice(1)).join(', ')}.</p><p><b>${ws.length+12} Aufgaben</b> insgesamt. Plane ungefähr 20 Minuten ein; es gibt kein Zeitlimit. Bilder, Merkhilfen und Lösungen erscheinen während der Probe nicht.</p><p>A und B prüfen denselben Wortschatz in anderer Reihenfolge und mit unterschiedlichen Formen. Eine passende Bedeutung reicht. Schreibhinweise werden getrennt ausgewertet.</p><div class="row"><button data-test="0">Kurzprobe A starten</button><button class="secondary" data-test="1">Kurzprobe B starten</button></div></section>${p().latinSession?'<p><button class="secondary" id="resumeSaved">Gespeicherte Runde fortsetzen</button></p>':''}`;document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>exam(+b.dataset.test));if($('#resumeSaved'))$('#resumeSaved').onclick=resume}
function exam(version){area='kurzproben';begin('Kurzprobe '+['A','B'][version]+' · '+PACKS[selectedPair].title,combinedQuestions(selectedPair,version),true)}
function overview(){if(area==='adverbien')adverbHome();else if(area==='kurzproben')testsHome(selectedPair);else packHome()}
function begin(title,qs,test=false){if(!initProfile())return route();session={title,qs,index:0,results:[],retry:[],test,area,pair:selectedPair};question()}
function resume(){session=p().latinSession;area=session.area;selectedPair=session.pair;if(session.results.length>session.index)session.index++;question()}
function question(){window.scrollTo({top:0,behavior:'auto'});if(session.index>=session.qs.length)return finish();answered=false;helped=false;triedTypo=false;p().latinSession=session;save();let q=session.qs[session.index],study=q.mode==='study';$('#app').innerHTML=`<div class="toolbar"><button class="secondary" id="pause">Pause / Übersicht</button><span>${esc(session.title)} · ${session.index+1}/${session.qs.length}</span></div><progress value="${session.index}" max="${session.qs.length}" aria-label="Fortschritt"></progress><section class="card guide"><div class="topic">${q.type==='form'?'Grammatik':study?'Vokabel · merken':q.mode==='choice'?'Vokabel · mit Auswahl':'Vokabel · selbst abrufen'}</div><h2>${q.type==='form'?'Bilde die verlangte Form.':q.dir==='de'?'Was bedeutet das?':'Wie heißt das auf Latein?'}</h2><p class="${q.type==='vocab'?'latin':'sentence'}">${esc(q.prompt)}</p><div id="work"></div><div id="feedback" aria-live="polite"></div></section>`;$('#pause').onclick=()=>{save();$('#app').innerHTML='<section class="card"><h1>Kurze Pause.</h1><p>Die Runde ist gespeichert. Beim Fortsetzen bleibst du im selben Doppelpack.</p><button id="resume">Fortsetzen</button> <button class="secondary" id="leave">Zur Übersicht</button></section>';$('#resume').onclick=question;$('#leave').onclick=()=>overview()};if(study){let w=q.word;$('#work').innerHTML=`<p><b>${esc(w.answers.join('; '))}</b></p>${figure(w)}<div class="anchor" id="currentAnchor">${esc(mnemonic(w))}</div>${w.small?'<button class="secondary" id="otherMnemonic">Andere Merkhilfe</button>':''}${w.sentence?`<p><i>${esc(w.sentence)}</i><br>${esc(w.translation)}</p>`:''}<p class="small muted">Stelle dir die Szene vor. Sage Wort und Bedeutung einmal laut.</p><details><summary>Eigene Merkhilfe speichern</summary><label for="note">Mein Satz oder Bild</label><input id="note" maxlength="240" value="${esc(p().notes[w.id]||'')}"><button class="secondary" id="saveNote">Speichern</button></details><p><button id="nextStudy">Gemerkt – weiter</button></p>`;if($('#otherMnemonic'))$('#otherMnemonic').onclick=()=>{switchMnemonic(w);$('#currentAnchor').textContent=mnemonic(w)};$('#saveNote').onclick=()=>{p().notes[w.id]=$('#note').value.trim();p().mnemonicChoices||={};p().mnemonicChoices[w.id]=p().notes[w.id]?2:0;save();$('#currentAnchor').textContent=mnemonic(w);$('#saveNote').textContent='Gespeichert'};$('#nextStudy').onclick=()=>{if(!p().seen.includes(w.id))p().seen.push(w.id);session.results.push({q,value:'angesehen',study:true,ok:true,independent:false});session.index++;question()};return}
if(q.mode==='choice'){let candidates=session.area==='adverbien'?adverbs():pairWords(q.word.pair);let used=new Set([q.word.answers.join('; ')]),others=shuffle(candidates.filter(w=>w.id!==q.id)).filter(w=>{let label=w.answers.join('; ');if(used.has(label))return false;used.add(label);return true}).slice(0,3);let options=[q.word,...others];$('#work').innerHTML=`${q.word.small?'<button class="secondary" id="pictureHint">Bildhilfe zeigen</button><div id="picture"></div>':''}${q.word.sentence?`<p><i>${esc(q.word.sentence)}</i></p>`:''}<div id="choices"></div>`;shuffle(options).forEach(w=>{let b=document.createElement('button');b.className='choice';b.textContent=w.answers.join('; ');b.onclick=()=>submit(b.textContent,w.id===q.id);$('#choices').append(b)});if($('#pictureHint'))$('#pictureHint').onclick=()=>{helped=true;$('#picture').innerHTML=figure(q.word);$('#pictureHint').disabled=true}}else{$('#work').innerHTML=`<form id="answerform"><label for="answer">${q.type==='vocab'&&q.dir==='de'?'Eine oder mehrere passende Bedeutungen:':'Deine Antwort:'}</label><input id="answer" autocomplete="off" autocapitalize="off" spellcheck="false"><p><button>${session.test?'Antwort abgeben':'Prüfen'}</button></p></form>${!session.test?'<button class="secondary" id="hint">Merkhilfe</button> <button class="secondary" id="unknown">Weiß ich noch nicht</button>':''}<p class="small muted">Längenzeichen sind optional. Bei Verben genügt im Vokabelteil der Infinitiv. Schreibhinweise werden getrennt von der Bedeutung angezeigt.</p>`;$('#answerform').onsubmit=e=>{e.preventDefault();submit($('#answer').value)};if(!session.test){$('#hint').onclick=()=>{helped=true;$('#hint').disabled=true;$('#feedback').innerHTML=(q.type==='vocab'?figure(q.word):'')+'<div class="anchor">'+esc(q.type==='form'?q.why:mnemonic(q.word))+'</div>'};$('#unknown').onclick=()=>submit('weiß ich noch nicht',false)}}}
function submit(value,forced){if(answered||!value.trim())return;let q=session.qs[session.index],result=forced===undefined?LatinCheck.assess(q,value):{ok:forced,kind:forced?'correct':'wrong',note:''};if(result.kind==='typo'&&!session.test&&!triedTypo){triedTypo=true;$('#feedback').innerHTML='<div class="warning">'+esc(result.note)+'<br>Du kannst deine Antwort ändern oder noch einmal „Prüfen“ wählen.</div>';return}answered=true;let independent=result.ok&&!helped&&q.mode!=='choice';session.results.push({q,value,ok:result.ok,independent,note:result.note||'',kind:result.kind});let st=stat(q.id);if(independent){st.ok=(st.ok||0)+1;st.due=Date.now()+[10,45,180][Math.min(st.ok-1,2)]*60000}else if(!result.ok){st.ok=0;st.errors=(st.errors||0)+1;st.due=Date.now()+120000;if(!session.test&&!session.retry.includes(q.id)&&session.retry.length<10){session.retry.push(q.id);session.qs.splice(Math.min(session.index+5,session.qs.length),0,{...q,mode:'write'})}}st.last=Date.now();p().stats[q.id]=st;save();if(session.test){session.index++;question();return}document.querySelectorAll('#work button,#work input').forEach(e=>e.disabled=true);$('#feedback').innerHTML=`<div class="feedback ${result.ok?'':'error'}"><strong>${result.ok?(result.kind==='writing'?'Inhaltlich richtig – mit Schreibhinweis.':independent?'Richtig – selbst abgerufen.':'Richtig – mit Auswahl oder Hilfe.'):'Noch üben.'}</strong>${result.note?`<p>${esc(result.note)}</p>`:''}<p>Lösung: <b>${esc(q.answers.join('; '))}</b></p><p>${esc(q.type==='form'?q.why:mnemonic(q.word))}</p></div><button id="next">Weiter</button>`;$('#next').onclick=()=>{session.index++;question()}}
function finish(){window.scrollTo({top:0,behavior:'auto'});let rs=session.results.filter(r=>!r.study),ok=rs.filter(r=>r.independent).length,correct=rs.filter(r=>r.ok).length;delete p().latinSession;p().history.push({title:session.title,ok,total:rs.length,date:Date.now(),type:session.test&&new Set(rs.map(r=>r.q.type)).size>1?'mixed':rs[0]?.q.type});save();let errors=rs.filter(r=>!r.ok),breakdown=session.test?`<div class="score-grid">${['vocab','form'].map(type=>{let list=rs.filter(r=>r.q.type===type);return list.length?`<div><b>${list.filter(r=>r.ok).length}/${list.length}</b><br>${type==='vocab'?'Vokabeln':'Grammatik'}</div>`:''}).join('')}<div><b>${rs.filter(r=>r.kind==='writing').length}</b><br>Schreibhinweise</div></div>`:'';$('#app').innerHTML=`<section class="card"><div class="topic">Runde abgeschlossen</div><h1>${correct}/${rs.length} Antworten richtig</h1><p>${ok} davon selbst ohne Auswahl oder Merkhilfe abgerufen.</p>${breakdown}<p>Rechtschreibhinweise werden getrennt von Wortbedeutung und Formen angezeigt.</p><button id="back">Zur Übersicht</button>${errors.length?' <button class="secondary" id="retry">Diese Fehler wiederholen</button>':''}</section><section class="card"><h2>Deine Auswertung</h2>${rs.map(r=>`<div class="result"><b>${r.ok?(r.note?'Inhaltlich richtig · Schreibhinweis':'Richtig'):'Noch üben'}</b> · ${esc(r.q.prompt)}<p>Deine Antwort: ${esc(r.value)}</p><p>Lösung: ${esc(r.q.answers.join('; '))}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<p class="small muted">${esc(r.q.type==='form'?r.q.why:mnemonic(r.q.word))}</p></div>`).join('')}</section>`;$('#back').onclick=()=>overview();if($('#retry'))$('#retry').onclick=()=>begin('Gezielte Wiederholung',[...new Map(errors.map(r=>[r.q.id,{...r.q,mode:'write'}])).values()])}
$('#profile').onclick=()=>location.href='../#profile';$('#share').onclick=()=>Workshop.share($('#share'));window.addEventListener('hashchange',route);window.addEventListener('focus',()=>{if(state.active!==Workshop.active()?.id){state=Workshop.readChapter('latin56-v1');route()}});Workshop.nav({learn:()=>area==='kurzproben'?testsHome(selectedPair):area==='adverbien'?startLearn(adverbs(),true):area==='grammatik'?rule(PACKS[selectedPair].groups[0]):startLearn(pairWords(selectedPair)),practice:()=>area==='kurzproben'?testsHome(selectedPair):area==='grammatik'?startForms():begin('Alle Wörter · eigener Abruf',(area==='adverbien'?adverbs():pairWords(selectedPair)).map(w=>vq(w))),repeat:()=>area==='kurzproben'?testsHome(selectedPair):repeat(area==='grammatik',area==='adverbien')});route();
